00091 static bool compare_packet_timestamps(const lctm::Packet &l, const lctm::Packet &r) {
00092     uint64_t lt = l.timestamp();
00093     uint64_t rt = r.timestamp();
00094     int64_t d = (rt - lt);
00095     return d < 0;
00096 }
00097 
00098 // PSS data that is queued whilst base frames are decoded
00099 typedef struct {
00100     Packet packet;
00101     bool is_lcevc_idr;
00102 } PssPacket;
00103 
00104 struct BufferCompare {
00105     bool operator()(const PssPacket &l, const PssPacket &r) { return compare_packet_timestamps(l.packet, r.packet); }
00106 };
00107 
00108 } // namespace
