00110 // Common code for external base decoders.
00111 //
00112 // Specialised for AVC/HEVC/VVC/EVC
00113 //
00114 class BaseVideoDecoderExternal : public BaseVideoDecoder {
00115 public:
00116     BaseVideoDecoderExternal(BaseVideoDecoder::Output &output, Encapsulation encapsulation,
00117                              const std::string &prepared_yuv_file_name, bool keep_base);
00118     ~BaseVideoDecoderExternal() override;
00119 
00120     void start() override;
00121     void stop() override;
00122 
00123     void push_au(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr, int iPictureType) override;
00124 
00125 protected:
00126     virtual BaseCoding base_coding() const = 0;
00127 
00128     virtual bool run_decoder(const string &input, const string &output) const = 0;
00129 
00130     void push_es(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr);
00131     void flush();
00132 
00133     // Consumer interface
00134     Output &output_;
00135 
00136     // Type of enhancement payload encapsulation
00137     Encapsulation encapsulation_;
00138 
00139     // If not-null -name of predecoded YUV base images
00140     const std::string prepared_yuv_file_name_;
00141 
00142     // Temp. files
00143     vector<uint8_t> buffer_;
00144 
00145     string es_file_name_;
00146     FILE *es_file_ = nullptr;
00147 
00148     string yuv_file_name_;
00149 
00150     // Keep base files
00151     bool keep_base_;
00152 
00153     // Priority queues of buffers for base & pss ordered by timestamp
00154     priority_queue<PssPacket, vector<PssPacket>, BufferCompare> enhancement_queue_;
00155     vector<PssPacket> enhancement_vector_;
00156 
00157     virtual void StatisticsComputation() override;
00158 
00159     // Size of base video - initisalized on first decoded base frame
00160     uint32_t base_buffer_size_ = 0;
00161     uint32_t base_width_ = 0;
00162     uint32_t base_height_ = 0;
00163     uint32_t base_bit_depth_ = 0;
00164 };
