00166 BaseVideoDecoderExternal::BaseVideoDecoderExternal(Output &output, Encapsulation encapsulation,
00167                                                    const std::string &prepared_yuv_file_name, bool keep_base)
00168     : output_(output), encapsulation_(encapsulation), prepared_yuv_file_name_(prepared_yuv_file_name), keep_base_(keep_base) {}
00169 
00170 BaseVideoDecoderExternal::~BaseVideoDecoderExternal() { stop(); }
00171 
00172 void BaseVideoDecoderExternal::start() {
00173 
00174     if (base_coding() != BaseCoding::BaseCoding_YUV) {
00175         // Create a temporary file for base ES
00176         es_file_name_ = make_temporary_filename("_base.es");
00177         es_file_ = CHECK(fopen(es_file_name_.c_str(), "wb"));
00178         INFO("Using temporary file for ES data: '%s'", es_file_name_.c_str());
00179     }
00180 
00181     if (prepared_yuv_file_name_.empty()) {
00182         // Create a temporary file for base YUV
00183         yuv_file_name_ = make_temporary_filename("_base.yuv");
00184 
00185         INFO("Using temporary file for YUV data: '%s'", yuv_file_name_.c_str());
00186     } else {
00187         INFO("Using prepared file for YUV data: '%s'", prepared_yuv_file_name_.c_str());
00188     }
00189 }
00190 
00191 static inline bool is_nal_marker(const uint8_t *data) { return data[0] == 0 && data[1] == 0 && data[2] == 1; }
00192 
00193 void BaseVideoDecoderExternal::push_au(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr, int iPictureType) {
00194     if (data) {
00195         // Temp. copy of AU
00196         vector<uint8_t> b(data, data + data_size);
00197 
00198         // Pick out enhancement data - may be removed - new size is returned
00199         size_t new_size = scan_enhancement(b.data(), data_size, encapsulation_, base_coding(), pts, is_base_idr,
00200                                            [this](const Packet &pkt, const bool is_lcevc_idr) {
00201                                                PacketView v(pkt);
00202                                                this->enhancement_queue_.push({pkt, is_lcevc_idr});
00203                                            });
00204 
00205         b.resize(new_size);
00206 
00207         goReportStructure.miTimeStamp = (int)(pts);
00208         goReportStructure.miPictureType = iPictureType;
00209         goReportStructure.miBaseSize = (int)(new_size);
00210         goReportStructure.miEnhancementSize = (int)(data_size - new_size);
00211         goReportQueue.push(goReportStructure);
00212 
00213         // Flush any previous buffer
00214         if (!buffer_.empty())
00215             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00216 
00217         buffer_.swap(b);
00218     } else {
00219         if (!buffer_.empty()) {
00220             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00221         }
00222 
00223         flush();
00224     }
00225 }
00226 
00227 void BaseVideoDecoderExternal::push_es(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr) {
00228     // Fixup NALU start code - if first is 3 bytes, make it 4
00229     if (data[0] == '\0' && data[1] == '\0' && data[2] == '\1') {
00230         char const zero = '\0';
00231         CHECK(fwrite(&zero, 1, 1, es_file_) == 1);
00232     }
00233 
00234     // Accumulate AUs into a temporary file
00235     CHECK(fwrite(data, 1, data_size, es_file_) == data_size);
00236 }
00237 
00238 void BaseVideoDecoderExternal::flush() {
00239 
00240     int iPictureCount = 0;
00241 
00242     if (base_coding() != BaseCoding::BaseCoding_YUV) {
00243         // Got end of input - finish up ES file
00244         fflush(es_file_);
00245         fclose(es_file_);
00246         es_file_ = nullptr;
00247     }
00248 
00249     while (!enhancement_queue_.empty()) {
00250         enhancement_vector_.push_back(std::move(const_cast<PssPacket &>(enhancement_queue_.top())));
00251         enhancement_queue_.pop();
00252     }
00253 
00254     if (keep_base_) {
00255         string es_enhancement_file_name_ = make_temporary_filename("_enhancement.es");
00256         FILE *es_enhancement_file_ = CHECK(fopen(es_enhancement_file_name_.c_str(), "wb"));
00257         INFO("Using temporary file for enhancement data: '%s'", es_enhancement_file_name_.c_str());
00258 
00259         for (auto const &element : enhancement_vector_) {
00260             const uint8_t nal_type = 28 + element.is_lcevc_idr;
00261             const uint8_t nalu_header[5] = {0x00, 0x00, 0x01, static_cast<uint8_t>(0x41 | (nal_type << 1)), 0xff};
00262             CHECK(fwrite(&nalu_header, 1, sizeof(nalu_header), es_enhancement_file_) == sizeof(nalu_header));
00263 
00264             Packet rbsp = rbsp_encapsulate(element.packet);
00265             const PacketView v(rbsp);
00266             CHECK(fwrite(v.data(), 1, v.size(), es_enhancement_file_) == v.size());
00267         }
00268 
00269         fflush(es_enhancement_file_);
00270         fclose(es_enhancement_file_);
00271         es_enhancement_file_ = nullptr;
00272     }
00273 
00274     Surface symbols_initial[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS];
00275     PssPacket pss_initial;
00276     if (!enhancement_vector_.empty()) {
00277         // Get PSS from queue
00278         pss_initial = enhancement_vector_.front();
00279         enhancement_vector_.erase(enhancement_vector_.begin());
00280 
00281         PacketView enhancement_view(pss_initial.packet);
00282         output_.deserialize_enhancement(enhancement_view.data(), enhancement_view.size(), symbols_initial);
00283         iPictureCount++;
00284     } else
00285         INFO("No LCEVC Data found in bitstream!");
00286 
00287     // Find base size
00288     //
00289     unsigned width = 0, height = 0, bit_depth = 0, chroma_format_idc = 0;
00290     if (prepared_yuv_file_name_.empty()) {
00291         if (!probe_es_file(es_file_name_, base_coding(), width, height, bit_depth, chroma_format_idc)) {
00292             ERR("Cannot get base size, depth, and chroma_format_idc");
00293             return;
00294         }
00295         if (iPictureCount > 0) {
00296             // Verify base dimensions with signalled LCEVC configuration
00297             Dimensions dimensions = output_.get_dimensions();
00298             CHECK(bit_depth == output_.get_base_bitdepth());
00299             CHECK(width == dimensions.base_width());
00300             CHECK(height == dimensions.base_height());
00301             CHECK(chroma_format_idc == output_.get_colourspace());
00302         }
00303     } else {
00304         // Get base dimensions from singalled LCEVC configuration
00305         if (iPictureCount == 0)
00306             ERR("No LCEVC Data and no base bitstream -> Cannot get width/height/format");
00307         Dimensions dimensions = output_.get_dimensions();
00308         width = dimensions.base_width();
00309         height = dimensions.base_height();
00310         bit_depth = output_.get_base_bitdepth();
00311         chroma_format_idc = output_.get_colourspace();
00312     }
00313 
00314     // Figure ESFile format
00315     YUVFormat::Enum format;
00316 
00317     switch (bit_depth) {
00318     case 8:
00319         format = static_cast<YUVFormat::Enum>(0 + (chroma_format_idc == 0 ? 3 : chroma_format_idc - 1));
00320         break;
00321 
00322     case 10:
00323         format = static_cast<YUVFormat::Enum>(4 + (chroma_format_idc == 0 ? 3 : chroma_format_idc - 1));
00324         break;
00325 
00326     case 12:
00327         format = static_cast<YUVFormat::Enum>(8 + (chroma_format_idc == 0 ? 3 : chroma_format_idc - 1));
00328         break;
00329 
00330     case 14:
00331         format = static_cast<YUVFormat::Enum>(12 + (chroma_format_idc == 0 ? 3 : chroma_format_idc - 1));
00332         break;
00333     default:
00334         CHECK(0);
00335         break;
00336     }
00337 
00338     YUVDesc yuv_desc;
00339     yuv_desc.Initialise(format, width, height);
00340     size_t base_size = yuv_desc.GetMemorySize();
00341 
00342     const char *fmt = "";
00343     YUVFormat::ToString(&fmt, format);
00344     INFO("Base is %s %dx%d %d bit (%zu bytes)\n", fmt, width, height, bit_depth, base_size);
00345 
00346     base_width_ = width;
00347     base_height_ = height;
00348     base_bit_depth_ = bit_depth;
00349 
00350     UniquePtrFile yuv_file;
00351 
00352     if (!prepared_yuv_file_name_.empty()) {
00353         // We have been given decoded YUV already
00354         yuv_file.reset(CHECK(fopen(prepared_yuv_file_name_.c_str(), "rb")));
00355     } else {
00356         // Run the decoder esfile->yuvfile
00357         //
00358         run_decoder(es_file_name_, yuv_file_name_);
00359 
00360         // Open temp. file
00361         yuv_file.reset(CHECK(fopen(yuv_file_name_.c_str(), "rb")));
00362     }
00363 
00364     // Buffer for the YUV frames
00365     vector<uint8_t> base(base_size);
00366 
00367     if (iPictureCount > 0) {
00368         // First frame: Copy data through, already deserialized previously
00369         CHECK(fread(base.data(), 1, base.size(), yuv_file.get()) == base.size());
00370         output_.push_base_enhancement(base.data(), base.size(), symbols_initial, pss_initial.packet.timestamp(),
00371                                       pss_initial.is_lcevc_idr);
00372 
00373         // Consume queue in PTS order
00374         while (!enhancement_vector_.empty()) {
00375             // Read base
00376             CHECK(fread(base.data(), 1, base.size(), yuv_file.get()) == base.size());
00377 
00378             // Get PSS from queue
00379             Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS];
00380             PssPacket pss = enhancement_vector_.front();
00381             enhancement_vector_.erase(enhancement_vector_.begin());
00382             PacketView enhancement_view(pss.packet);
00383             output_.deserialize_enhancement(enhancement_view.data(), enhancement_view.size(), symbols);
00384             output_.push_base_enhancement(base.data(), base.size(), symbols, pss.packet.timestamp(), pss.is_lcevc_idr);
00385             iPictureCount++;
00386         }
00387 
00388         int iFrames = iPictureCount;
00389 
00390         float fAccMse[3];
00391         float fPsnr[3];
00392         for (unsigned plane = 0; plane < yuv_desc.GetPlaneCount(); plane++) {
00393             fAccMse[plane] = goPsnr.mfAccMse[plane] / iFrames;
00394             fPsnr[plane] = (float)(10.0f * log10((32767.0f * 32767.0f) / fAccMse[plane]));
00395         }
00396         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00397         if (yuv_desc.GetPlaneCount() > 1)
00398             REPORT("PSNR -- YUV %8.4f -- Y %8.4f U %8.4f V %8.4f", (6 * fPsnr[0] + fPsnr[1] + fPsnr[2]) / 8, fPsnr[0], fPsnr[1],
00399                    fPsnr[2]);
00400         else
00401             REPORT("PSNR -- Y %8.4f", fPsnr[0]);
00402         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00403         REPORT("BITS -- base %8d bps -- enha %8d bps ", (goPsnr.miBaseBytes * 8 * /* this->fps_ */ 60) / iFrames,
00404                (goPsnr.miEnhancementBytes * 8 * /* this->fps_ */ 60) / iFrames);
00405         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00406     }
00407 }
00408 
00409 void BaseVideoDecoderExternal::stop() {
00410     if (!keep_base_) {
00411         if (!es_file_name_.empty())
00412             ::remove(es_file_name_.c_str());
00413 
00414         if (!yuv_file_name_.empty())
00415             ::remove(yuv_file_name_.c_str());
00416     }
00417 }
00418 
