00422 // RBSP encapsualtion (0b00000000 0b00000000 0b000000xx -> 0b00000000 0b00000000 0b00000011 0b000000xx)
00423 //
00424 Packet BaseVideoDecoder::rbsp_encapsulate(const Packet &src) const {
00425     PacketView in(src);
00426 
00427     vector<uint8_t> out;
00428 
00429     unsigned zeros = 0;
00430     for (unsigned int i = 0; i < in.size(); ++i) {
00431         uint8_t b = in.data()[i];
00432 
00433         if (zeros == 2 && (b & ~3) == 0) {
00434             out.push_back(0x03);
00435             zeros = 0;
00436         }
00437 
00438         if (b == 0)
00439             ++zeros;
00440         else
00441             zeros = 0;
00442 
00443         out.push_back(b);
00444     }
00445 
00446     out.push_back(0x80);
00447 
00448     return Packet::build().contents(out).finish();
00449 }
