00453 class BaseVideoDecoderExternalAVC : public BaseVideoDecoderExternal {
00454 public:
00455     BaseVideoDecoderExternalAVC(BaseVideoDecoder::Output &output, Encapsulation encapsulation, const std::string &yuv_file,
00456                                 bool keep_base)
00457         : BaseVideoDecoderExternal(output, encapsulation, yuv_file, keep_base) {}
00458 
00459     BaseCoding base_coding() const override { return BaseCoding_AVC; };
00460 
00461     bool run_decoder(const string &es_file, const string &yuv_file) const override {
00462         string p = get_program_directory("external_codecs/JM/ldecod");
00463 
00464         INFO("Using base decoder %s", p.c_str());
00465 
00466         int r = system(
00467             format("%s -p InputFile=%s -p OutputFile=%s -p WriteUV=0", p.c_str(), es_file.c_str(), yuv_file.c_str()).c_str());
00468 
00469         return r == 0;
00470     }
00471 
00472     virtual void StatisticsComputation() override{};
00473 };
