00563 // Factory function
00564 //
00565 unique_ptr<BaseVideoDecoder> CreateBaseVideoDecoder(BaseVideoDecoder::Output &output, BaseCoding base, Encapsulation encapsulation,
00566                                                     bool external, const std::string &yuv_file, bool keep_base) {
00567 
00568     try {
00569         if (external || keep_base || !yuv_file.empty()) {
00570             if (base == BaseCoding_AVC)
00571                 return unique_ptr<BaseVideoDecoder>(new BaseVideoDecoderExternalAVC(output, encapsulation, yuv_file, keep_base));
00572             else if (base == BaseCoding_HEVC)
00573                 return unique_ptr<BaseVideoDecoder>(new BaseVideoDecoderExternalHEVC(output, encapsulation, yuv_file, keep_base));
00574             else if (base == BaseCoding_VVC)
00575                 return unique_ptr<BaseVideoDecoder>(new BaseVideoDecoderExternalVVC(output, encapsulation, yuv_file, keep_base));
00576             else if (base == BaseCoding_EVC)
